#!/usr/bin/env bash
# L-SI box 86 LAG TOWER (docs/si/box86-lagtower.md) self-check: pins; instances regenerated byte-equal from cfg/ (lag86.py); every
# output recomputed (runout86.sh) and diffed with out/; FLIP-U, LOWER-BLIND, PRIV-FLIP, POOL-ALT, ACCESS-LATCH never exceeded.
set -euo pipefail
cd "$(dirname "$0")"
sha1sum -c --quiet --strict pins.sha1
cmp -s gen83.py ../box83/gen83.py
t=$(mktemp -d); bash runout86.sh "$t"
for f in inst/*.json; do cmp -s "$f" "$t/inst/$(basename "$f")"; done
for f in out/*.out; do diff -q "$f" "$t/out/$(basename "$f")"; done
! grep -E "exU [1-9]|exE [1-9]" out/flipu85.out
! grep -v "mispredictions 0 " out/lb84.out
! grep -v "POOL-ALT violations 0" out/pool85.out
! grep -E "maxex_priv [1-9]|maxex_nopriv [1-9]" out/priv84.out
! grep -v "latch-violations 0$" out/latch86.out
rm -rf "$t"
echo "box 86 checks: PASS"
